        case .reverse_crunch:return .init(asset:"exercise_reverse_crunch",variant:arabic ? "كرنش عكسي" : "Reverse crunch",cues:arabic ? ["استلقِ على الظهر والركبتان مثنيتان والذراعان بجانب الجسم.","قرّب الحوض نحو الضلوع برفعة صغيرة متحكم بها.","انزل ببطء دون تأرجح الرجلين."] : ["Lie on the back with bent knees and arms resting at the sides.","Curl the pelvis toward the ribs with a small controlled lift.","Lower slowly without swinging the legs."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .cable_crunch:return .init(asset:"exercise_cable_crunch",variant:arabic ? "كرنش بالكابل من الركوع" : "Kneeling cable crunch",cues:arabic ? ["اركع أمام بكرة علوية والحبل بجانب الرأس.","قرّب الضلوع نحو الحوض بدلًا من السحب بالذراعين.","ارجع بتحكم مع ثبات الفخذين نسبيًا."] : ["Kneel facing a high pulley with the rope held beside the head.","Curl the ribs toward the pelvis rather than pulling with the arms.","Return with control while keeping hips relatively still."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .barbell_bench_press:return .init(asset:"exercise_barbell_bench_press",variant:arabic ? "ضغط الصدر بالبار على مقعد أفقي" : "Flat barbell bench press",cues:arabic ? ["استلقِ على المقعد مع ثبات القدمين وامسك البار أوسع قليلًا من الكتفين.","اخفض البار بتحكم نحو منتصف الصدر مع ضم المرفقين قليلًا.","ادفع لأعلى مع استقامة الرسغين وثبات الكتفين."] : ["Lie flat with feet planted and grip the bar slightly wider than shoulder width.","Lower the bar smoothly to mid-chest with elbows tucked roughly 45 degrees.","Press back up with straight wrists and stable shoulders."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .incline_barbell_press:return .init(asset:"exercise_incline_barbell_press",variant:arabic ? "ضغط صدر مائل بالبار" : "Incline barbell bench press",cues:arabic ? ["اضبط المقعد على ميل متوسط واسند الظهر وثبّت القدمين.","اخفض البار نحو أعلى الصدر مع بقاء الساعدين رأسيين.","ادفع لأعلى بسلاسة دون ارتداد على الصدر."] : ["Set a moderate incline and keep upper back and feet firmly supported.","Lower the barbell to the upper chest with vertical forearms.","Press smoothly upward without bouncing off the chest."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .dip:return .init(asset:"exercise_dip",variant:arabic ? "متوازي للصدر والترايسبس" : "Parallel bar dip",cues:arabic ? ["ابدأ والذراعان مفرودتان مع خفض الكتفين وميل بسيط للأمام.","انزل بتحكم حتى يوازي أعلى الذراعين الأرض تقريبًا.","ادفع لأعلى دون رفع الكتفين نحو الأذنين."] : ["Start on straight arms with shoulders depressed and a slight forward lean.","Lower under control until upper arms are roughly parallel to the floor.","Press back up without shrugging the shoulders."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .conventional_deadlift:return .init(asset:"exercise_conventional_deadlift",variant:arabic ? "ديدلفت تقليدي بالبار" : "Conventional barbell deadlift",cues:arabic ? ["قف ومنتصف القدم أسفل البار واثنِ من الحوض وامسك البار خارج الركبتين.","شد الجذع وأبقِ البار قريبًا من الساقين والفخذين أثناء الصعود.","قف مستقيمًا بمد الحوض دون الميل للخلف."] : ["Stand with mid-foot under the bar, hinge at the hips and grip just outside the knees.","Brace the trunk and keep the bar close to the shins and thighs as you stand.","Lock out tall by extending the hips without leaning backward."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .barbell_row:return .init(asset:"exercise_barbell_row",variant:arabic ? "تجديف بالبار" : "Bent-over barbell row",cues:arabic ? ["انحنِ للأمام بظهر محايد وثني خفيف للركبتين والبار مفرود الذراعين.","اسحب البار نحو أسفل الضلوع مع توجيه المرفقين للخلف.","اخفضه بتحكم دون تأرجح الجذع."] : ["Hinge forward with a neutral spine and soft knees, holding the bar at arm's length.","Pull the barbell toward the lower ribs while driving the elbows back.","Lower with control without letting the torso bob up and down."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .barbell_overhead_press:return .init(asset:"exercise_barbell_overhead_press",variant:arabic ? "ضغط كتف واقفًا بالبار" : "Standing barbell overhead press",cues:arabic ? ["ابدأ والبار عند أعلى الصدر والساعدان في وضع رأسي.","شد الجذع وادفع البار لأعلى مباشرة فوق الرأس.","اخفضه بسلاسة دون زيادة تقوّس أسفل الظهر."] : ["Start with the bar resting at the upper chest and forearms stacked vertically.","Brace your trunk and press the bar straight overhead.","Lower smoothly back to the front rack without arching the lower back."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .cable_lateral_raise:return .init(asset:"exercise_cable_lateral_raise",variant:arabic ? "رفرفة جانبية بالكابل بذراع واحدة" : "Single-arm cable lateral raise",cues:arabic ? ["قف مستقيمًا بجانب بكرة منخفضة وامسك المقبض بثني خفيف للمرفق.","ارفع الذراع للجانب حتى مستوى الكتف دون رفع الكتفين.","اخفضه بتحكم وسجّل التكرارات لكل جانب."] : ["Stand tall beside a low pulley and hold the handle with a slight elbow bend.","Raise the arm smoothly out to shoulder height without shrugging.","Lower with control and log repetitions per side."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .barbell_curl:return .init(asset:"exercise_barbell_curl",variant:arabic ? "بايسبس واقفًا بالبار" : "Standing barbell biceps curl",cues:arabic ? ["قف مستقيمًا بقبضة سفلية بعرض الكتفين والمرفقان بجانب الجسم.","اثنِ المرفقين لرفع البار نحو الكتفين دون تأرجح الجذع.","اخفضه بتحكم حتى المد المريح."] : ["Stand tall with an underhand shoulder-width grip and elbows close to your sides.","Curl the bar smoothly toward the shoulders without swinging the torso.","Lower under control to full comfortable extension."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .skull_crusher:return .init(asset:"exercise_skull_crusher",variant:arabic ? "ترايسبس نائم بالبار" : "Lying barbell triceps extension",cues:arabic ? ["استلقِ على المقعد وامسك البار فوق الكتفين والذراعان مفرودتان.","اثنِ المرفقين فقط لخفض البار بتحكم فوق الجبهة أو خلفها قليلًا.","افرد المرفقين للرجوع مع ثبات أعلى الذراعين."] : ["Lie flat on a bench holding the bar above your shoulders with straight arms.","Bend only at the elbows to lower the bar smoothly above or behind the forehead.","Extend the elbows back to the start while keeping upper arms steady."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .hanging_leg_raise:return .init(asset:"exercise_hanging_leg_raise",variant:arabic ? "رفع الأرجل معلقًا" : "Hanging leg raise",cues:arabic ? ["تعلّق بثبات على عقلة مع تفعيل الكتفين واستقامة الرجلين.","ارفع الرجلين للأمام حتى الوضع الأفقي تقريبًا باستخدام البطن.","انزل ببطء دون تأرجح الجسم."] : ["Hang steadily from a pull-up bar with engaged shoulders and legs straight.","Raise the legs forward to roughly horizontal using your core.","Lower slowly without swinging your body."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/")
        case .dumbbell_chest_fly:return .init(asset:"exercise_dumbbell_chest_fly",variant:arabic ? "تفتيح صدر مسطح بالدمبل" : "Flat dumbbell chest fly",cues:arabic ? ["استلقِ على المقعد وثبّت قدميك وارفع الدمبل فوق الصدر مع ثني بسيط للمرفقين.","افتح الذراعين للخارج بقوس متحكّم حتى تشعر بتمدد مريح في الصدر.","أعد الدمبل معًا بسلاسة فوق الصدر من غير تصادم."] : ["Lie flat with feet planted and hold dumbbells above chest with soft elbows.","Open arms wide in a controlled arc until you feel a comfortable chest stretch.","Bring the dumbbells back together smoothly without clanking them."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/38/chest-fly/")
        case .pec_deck_fly:return .init(asset:"exercise_pec_deck_fly",variant:arabic ? "تفتيح صدر جالسًا على جهاز الفراشة" : "Seated machine pec deck fly",cues:arabic ? ["اضبط ارتفاع المقعد بحيث تكون المقابض بمستوى منتصف الصدر وظهرك مستندًا.","قرّب الذراعين بسلاسة أمام الصدر مع استقرار الكتفين.","ارجع ببطء حتى تمدد مريح من غير انحناء الكتفين للأمام."] : ["Adjust seat height so handles align with mid-chest and keep your back flat.","Bring the arms smoothly together in front of your chest with relaxed shoulders.","Return slowly to a comfortable stretch without letting shoulders roll forward."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/188/seated-chest-press/")
        case .straight_arm_pulldown:return .init(asset:"exercise_straight_arm_pulldown",variant:arabic ? "سحب كابل علوي بذراعين مستقيمتين واقفًا" : "Standing straight-arm cable pulldown",cues:arabic ? ["قف أمام البكرة العلوية مع ميل بسيط من الحوض وظهر محايد.","اسحب البار لأسفل بقوس نحو الفخذين مع ثبات المرفقين.","ارجع ببطء للأعلى مع ثبات الجذع وخفض الكتفين."] : ["Stand facing the high pulley with a slight hip hinge and neutral spine.","Sweep the bar down in an arc toward your thighs with softly locked elbows.","Return slowly overhead while keeping ribs stacked and shoulders down."],reference:"https://www.nasm.org/resource-center/blog/training/the-biomechanics-of-the-lat-pulldown-muscles-grip-and-form")
        case .pendlay_row:return .init(asset:"exercise_pendlay_row",variant:arabic ? "سحب بندلاي بالبار من الأرض" : "Dead-stop Pendlay barbell row",cues:arabic ? ["امِل بالجذع للأمام حتى يقترب من التوازي مع الأرض مع شد الظهر.","اسحب البار بقوة وتحكّم من الأرض لأسفل الصدر مع ثبات الجذع.","أنزل البار للأرض بتحكّم لتوقف لحظي قبل التكرار التالي."] : ["Hinge forward until your torso is nearly parallel to the floor with a braced back.","Row the bar briskly from the floor to your lower chest while keeping torso still.","Lower the bar under control to a brief reset on the floor before the next rep."],reference:"https://www.nasm.org/resource-center/exercise-library/barbell-bent-over-row")
        case .back_extension:return .init(asset:"exercise_back_extension",variant:arabic ? "تمديد الظهر على الكرسي المائل ٤٥ درجة" : "45° Roman chair back extension",cues:arabic ? ["اضبط الوسادة أسفل مفصل الحوض مباشرة لتتحرك من الحوض.","انزل بالجذع بسلاسة مع الحفاظ على استقامة الظهر.","اصعد بشد الأرداف والظهر حتى يصبح جسمك في خط مستقيم من غير تقوّس مبالغ."] : ["Position the pad just below your hip crease so you hinge at the hips.","Lower your torso smoothly with a long, neutral spine.","Raise up by squeezing glutes and back until your body forms a straight line."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/41/back-extensions/")
        case .front_raise:return .init(asset:"exercise_front_raise",variant:arabic ? "رفرفة أمامية بالدمبل واقفًا" : "Standing dumbbell front raise",cues:arabic ? ["قف باستقامة مع الدمبل أمام الفخذين وثني بسيط للمرفقين.","ارفع الأوزان للأمام بتحكّم حتى مستوى الكتف من غير تأرجح.","انزل ببطء للبداية مع إبقاء الكتفين مسترخيين."] : ["Stand tall with dumbbells resting in front of your thighs and soft elbows.","Raise the weights forward with control up to shoulder height without swinging.","Lower slowly back to the start while keeping shoulders relaxed."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/106/front-raise/")
        case .incline_dumbbell_curl:return .init(asset:"exercise_incline_dumbbell_curl",variant:arabic ? "ثني الذراعين بالدمبل على مقعد مائل ٤٥ درجة" : "Seated 45° incline dumbbell curl",cues:arabic ? ["اسند ظهرك على مقعد مائل واترك الذراعين ممدودتين للأسفل خلف الجذع.","اثنِ الذراعين بالدمبل بسلاسة مع ثبات العضدين بجانب الجسم.","انزل بالكامل بتحكّم حتى تشعر بتمدد مريح."] : ["Lean back on an incline bench with arms hanging straight down behind your torso.","Curl the dumbbells smoothly while keeping upper arms still beside your sides.","Lower all the way down with control to feel a gentle stretch."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/166/biceps-curl/")
        case .concentration_curl:return .init(asset:"exercise_concentration_curl",variant:arabic ? "ثني بايسبس تركيز بذراع واحدة جالسًا" : "Seated single-arm concentration curl",cues:arabic ? ["اجلس على المقعد وثبّت الجزء الخلفي من العضد على الفخذ الداخلي.","ارفع الدمبل بسلاسة نحو الكتف مع ثبات المرفق تمامًا.","انزل ببطء حتى فرد كامل متحكّم وكرّر للذراع الأخرى."] : ["Sit on a bench and brace the back of your working upper arm against your inner thigh.","Curl the dumbbell smoothly toward your shoulder without moving your elbow.","Lower slowly to a full controlled extension and repeat both sides."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/166/biceps-curl/")
        case .bulgarian_split_squat:return .init(asset:"exercise_bulgarian_split_squat",variant:arabic ? "سكوات بلغاري بالدمبل مع رفع القدم الخلفية" : "Rear-foot-elevated dumbbell split squat",cues:arabic ? ["ضع القدم الخلفية بخفة على المقعد وثبّت القدم الأمامية بالكامل على الأرض.","انزل بالحوض لأسفل وللخلف قليلًا حتى يقترب الفخذ الأمامي من التوازي مع الأرض.","ادفع بكامل القدم الأمامية للوقوف وكرّر للرجل الأخرى."] : ["Rest your back foot lightly on a bench behind you and keep your front foot planted.","Lower your hips straight down and slightly back until the front thigh nears parallel.","Drive through your full front foot to stand tall and repeat both sides."],reference:"https://www.nasm.org/resource-center/exercise-library/bulgarian-split-squat")
        case .front_squat:return .init(asset:"exercise_front_squat",variant:arabic ? "سكوات أمامي بالبار على الكتفين" : "Barbell front-rack squat",cues:arabic ? ["ضع البار على الكتفين من الأمام مع رفع المرفقين عاليًا وصدر مرفوع.","انزل للسكوات بسلاسة مع الحفاظ على استقامة الجذع والركبتين باتجاه الأصابع.","أبقِ الكعبين ثابتين والمرفقين مرفوعين أثناء الصعود."] : ["Rest the bar across your front shoulders with elbows lifted high and chest tall.","Squat down smoothly keeping your torso upright and knees tracking over toes.","Keep heels planted and elbows high as you stand back up."],reference:"https://www.nasm.org/resource-center/exercise-library/barbell-front-squat")
        case .plank:return .init(asset:"exercise_plank",variant:arabic ? "بلانك ثابت على الساعدين" : "Braced forearm plank",cues:arabic ? ["ضع الساعدين بعرض الكتفين والمرفقين أسفل الكتفين مباشرة.","شد البطن والأرداف ليشكّل جسمك خطًا مستقيمًا من الرأس حتى الكعبين.","تنفّس بانتظام من غير هبوط الحوض أو رفعه للأعلى."] : ["Place forearms shoulder-width apart with elbows directly beneath your shoulders.","Brace your core and glutes so your body forms a straight line from head to heels.","Breathe steadily without letting your hips sag or pike upward."],reference:"https://www.acefitness.org/resources/everyone/exercise-library/32/front-plank/")
        }
    }
